async function viewFamily(e){const t=await api("/family/members"),a="admin"===ME.role;e.innerHTML=`<div class="pagehead"><div><h1>Family</h1><p>Everyone shares the same data. Admins manage members, adults can edit, children can only view.</p></div></div>\n    ${a?`<div class="card"><h3>Invite someone</h3>\n      <p>Share this code — they choose <b>Register</b> on the sign-in screen:</p>\n      <p class="row"><span class="amount" id="invcode" style="font-size:22px;letter-spacing:.12em">${esc(FAMILY.invite_code)}</span>\n      <button class="btn ghost small" data-copy="${esc(FAMILY.invite_code)}">Copy code</button>\n      <button class="btn ghost small" id="rotate">Generate new code</button></p>\n      <p style="margin:8px 0"><label>Or send this link — it opens Register with the code filled in:</label>\n      <span class="row"><input readonly value="${esc(inviteLink())}" class="selectall" style="flex:1;min-width:200px;font-size:14px">\n      <button class="btn ghost small" data-copy="${esc(inviteLink())}">Copy link</button></span></p>\n      <p class="muted">New members join as adults. Change their role below after they join.</p>\n      <form id="inviteform" class="row" style="margin-top:12px;align-items:flex-end">\n        <div style="flex:1;min-width:180px"><label>Or email an invite</label><input name="email" type="email" placeholder="person@email.com" required></div>\n        <button class="btn small">Send invite</button></form></div>`:""}\n    ${a?'<div class="card" style="margin-top:16px"><h3>Add a child (no account)</h3>\n      <p class="muted">For kids without an email — they show up in the family and can have acte and expenses linked to them, but can\'t sign in.</p>\n      <form id="childform" class="formgrid"><div><label>Name</label><input name="name" required></div>\n      <button class="btn">Add child</button></form></div>':""}\n    <div class="card" style="margin-top:16px"><h3>Members</h3>\n      <table><thead><tr><th>Name</th><th>Email</th><th>Role</th>${a?"<th></th>":""}</tr></thead><tbody>\n      ${t.map(e=>`<tr><td><span class="row" style="gap:8px">${avatarHtml(e)}<span>${esc(e.name)}${e.id===ME.id?' <span class="muted">(you)</span>':""}</span></span></td><td>${e.email?esc(e.email):'<span class="muted">no login</span>'}</td>\n        <td>${a&&e.id!==ME.id&&e.email?`<select data-role="${e.id}">${["admin","adult","child"].map(t=>`<option value="${t}" ${t===e.role?"selected":""}>${t}</option>`).join("")}</select>`:`<span class="badge role">${tr(e.role)}</span>`}</td>\n        ${a?`<td class="right">${e.id!==ME.id?`<button class="btn danger small" data-del="${e.id}">Remove</button>`:""}</td>`:""}</tr>`).join("")}\n      </tbody></table></div>\n    ${a?`<div class="card" style="margin-top:16px"><h3>Family settings</h3>\n      <form id="famform" class="formgrid">\n        <div><label>Family name</label><input name="name" value="${esc(FAMILY.name)}"></div>\n        <div><label>Currency</label><select name="currency">${Object.entries(CURRENCIES).map(([e,t])=>`<option value="${e}" ${e===FAMILY.currency?"selected":""}>${e}${e===t?"":` (${t})`}</option>`).join("")}</select></div>\n        <button class="btn">Save</button></form>\n        <p class="muted" style="margin:12px 0 0;font-size:12px">${tr("Changing this relabels existing amounts — it does not convert them.")}</p></div>`:""}`,$("#rotate")?.addEventListener("click",async()=>{const t=await api("/family/invite/rotate",{method:"POST"});FAMILY.invite_code=t.invite_code,viewFamily(e)}),e.querySelectorAll("[data-copy]").forEach(e=>e.onclick=()=>copyText(e.dataset.copy)),$("#inviteform")?.addEventListener("submit",async e=>{e.preventDefault();const t=new FormData(e.target).get("email");try{await api("/family/invite/email",{method:"POST",body:{email:t}}),toast(tr("Invite sent to")+" "+t),e.target.reset()}catch(e){toast(e.message)}}),$("#childform")?.addEventListener("submit",async t=>{t.preventDefault();try{await api("/family/members",{method:"POST",body:Object.fromEntries(new FormData(t.target))}),toast("Child added"),viewFamily(e)}catch(e){toast(e.message)}}),e.querySelectorAll("[data-role]").forEach(t=>t.onchange=async()=>{try{await api("/family/members/"+t.dataset.role,{method:"PATCH",body:{role:t.value}}),toast("Role updated")}catch(t){toast(t.message),viewFamily(e)}}),e.querySelectorAll("[data-del]").forEach(t=>t.onclick=async()=>{await askDelete({en:"member",ro:"membrul",name:rowName(t),verbEn:"Remove",verbRo:"Elimină",detailEn:"Their account is deleted.",detailRo:"Contul lui se șterge."})&&(await api("/family/members/"+t.dataset.del,{method:"DELETE"}),viewFamily(e))}),$("#famform")?.addEventListener("submit",async e=>{e.preventDefault();const t=Object.fromEntries(new FormData(e.target));await api("/family",{method:"PATCH",body:t});const a=await api("/me");FAMILY=a.family,toast("Saved"),render()})}